import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Modal from '../../../components/ui/Modal';
import { formatLuc, formatNaira, lucToNaira } from '../../../utils/currencyUtils';
import SendCreditsModal from './SendCreditsModal';

const LUCWallet = ({ userId }) => {
    const { addToast } = useToast();
    const [wallet, setWallet] = useState({ balance: 0, total_earned: 0 });
    const [transactions, setTransactions] = useState([]);
    const [withdrawals, setWithdrawals] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSendModalOpen, setIsSendModalOpen] = useState(false);
    const [isWithdrawModalOpen, setIsWithdrawModalOpen] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [withdrawForm, setWithdrawForm] = useState({
        amount: '',
        bank_name: '',
        account_number: '',
        account_name: ''
    });

    useEffect(() => {
        if (userId) {
            fetchWalletData();
        }
    }, [userId]);

    const fetchWalletData = async () => {
        setIsLoading(true);
        try {
            const [walletData, transactionsData, withdrawalsData] = await Promise.all([
                supabaseService.getUserWallet(userId),
                supabaseService.getWalletTransactions(userId),
                supabaseService.getUserLucWithdrawals(userId)
            ]);
            setWallet(walletData);
            setTransactions(transactionsData);
            setWithdrawals(withdrawalsData);
        } catch (error) {
            console.error('Failed to fetch LUC wallet data:', error);
            addToast('Failed to load your wallet data', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleWithdrawRequest = async (e) => {
        e.preventDefault();
        const amount = parseFloat(withdrawForm.amount);
        
        if (amount < 100) {
            addToast('Minimum withdrawal is 100 LUC', 'warning');
            return;
        }
        if (amount > wallet.balance) {
            addToast('Insufficient balance', 'error');
            return;
        }

        setIsSubmitting(true);
        try {
            await supabaseService.requestLucWithdrawal(userId, amount, {
                bank_name: withdrawForm.bank_name,
                account_number: withdrawForm.account_number,
                account_name: withdrawForm.account_name
            });
            addToast('Withdrawal request submitted! Admin will process it shortly.', 'success');
            setIsWithdrawModalOpen(false);
            setWithdrawForm({ amount: '', bank_name: '', account_number: '', account_name: '' });
            fetchWalletData();
        } catch (error) {
            addToast('Failed to submit withdrawal request', 'error');
        } finally {
            setIsSubmitting(false);
        }
    };

    const formatAmount = (amount) => {
        return new Intl.NumberFormat().format(amount);
    };

    const getTransactionIcon = (type) => {
        switch (type) {
            case 'course_completion': return 'GraduationCap';
            case 'peer_review': return 'Users';
            case 'course_purchase': return 'ShoppingCart';
            case 'daily_login': return 'Calendar';
            case 'bonus': return 'Gift';
            case 'withdrawal': return 'Banknote';
            default: return 'CircleDollarSign';
        }
    };

    const getTransactionColor = (amount) => {
        return amount > 0 ? 'text-emerald-400' : 'text-red-400';
    };

    const pendingWithdrawals = withdrawals.filter(w => w.status === 'pending');

    return (
        <div className="space-y-8 animate-in fade-in duration-700">
            {/* Header Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Main Balance Card */}
                <div className="bg-gradient-to-br from-indigo-600 via-blue-600 to-cyan-500 rounded-[2.5rem] p-8 shadow-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/10 rounded-full blur-3xl group-hover:scale-110 transition-transform duration-700" />
                    
                    <div className="relative z-10">
                        <div className="flex items-center gap-3 mb-6">
                            <div className="w-10 h-10 rounded-2xl bg-white/20 flex items-center justify-center backdrop-blur-md">
                                <Icon name="Coins" size={20} className="text-white" />
                            </div>
                            <span className="text-white/80 font-bold uppercase tracking-widest text-xs">Current Balance</span>
                        </div>
                        
                        <div className="flex items-baseline gap-3">
                            <h2 className="text-5xl md:text-6xl font-black text-white tracking-tighter">
                                {formatAmount(wallet.balance)}
                            </h2>
                            <div className="flex flex-col">
                                <span className="text-xl font-bold text-white/70">LUC</span>
                                <span className="text-xs font-bold text-white/50 tracking-wide">≈ {formatNaira(lucToNaira(wallet.balance))}</span>
                            </div>
                        </div>
                        
                        <div className="mt-8 flex flex-wrap gap-3">
                            <Button className="bg-white text-indigo-600 hover:bg-white/90 border-none rounded-2xl px-6 font-bold shadow-lg">
                                Buy Credits
                            </Button>
                            <Button 
                                onClick={() => setIsSendModalOpen(true)}
                                variant="outline" 
                                className="border-white/30 text-white hover:bg-white/10 rounded-2xl px-6 font-bold"
                            >
                                Send Credits
                            </Button>
                            <Button 
                                onClick={() => setIsWithdrawModalOpen(true)}
                                variant="outline" 
                                className="border-white/30 text-white hover:bg-white/10 rounded-2xl px-6 font-bold"
                            >
                                Withdraw
                            </Button>
                        </div>
                    </div>
                </div>

                {/* Total Earned Card */}
                <div className="bg-card border border-border rounded-[2.5rem] p-8 shadow-xl flex flex-col justify-between">
                    <div>
                        <div className="flex items-center gap-3 mb-6">
                            <div className="w-10 h-10 rounded-2xl bg-primary/10 flex items-center justify-center">
                                <Icon name="TrendingUp" size={20} className="text-primary" />
                            </div>
                            <span className="text-muted-foreground font-bold uppercase tracking-widest text-xs">Lifetime Earnings</span>
                        </div>
                        <h3 className="text-4xl font-black text-foreground tracking-tighter">
                            {formatAmount(wallet.total_earned)} <span className="text-sm font-medium text-muted-foreground tracking-normal">LUC</span>
                        </h3>
                    </div>
                    
                    <div className="mt-6 p-4 bg-muted/30 rounded-2xl border border-border/50">
                        <p className="text-xs text-muted-foreground leading-relaxed">
                            <Icon name="Info" size={12} className="inline mr-1" />
                            You earn **LUC Credits** for course milestones, peer feedback, and community engagement. 
                            Use them to unlock premium mentorship sessions or request withdrawal to your bank account.
                        </p>
                    </div>
                </div>
            </div>

            {/* Pending Withdrawals Alert */}
            {pendingWithdrawals.length > 0 && (
                <div className="bg-amber-500/10 border border-amber-500/20 rounded-2xl p-6 flex items-center gap-4">
                    <div className="w-12 h-12 rounded-xl bg-amber-500/20 flex items-center justify-center text-amber-500 flex-shrink-0">
                        <Icon name="Clock" size={24} />
                    </div>
                    <div>
                        <p className="font-bold text-amber-500">
                            {pendingWithdrawals.length} withdrawal request{pendingWithdrawals.length > 1 ? 's' : ''} pending
                        </p>
                        <p className="text-xs text-amber-500/70 mt-0.5">
                            Total: {formatAmount(pendingWithdrawals.reduce((sum, w) => sum + w.amount_luc, 0))} LUC ≈ {formatNaira(pendingWithdrawals.reduce((sum, w) => sum + w.amount_naira, 0))}
                        </p>
                    </div>
                </div>
            )}

            {/* Transaction History */}
            <div className="bg-card border border-border rounded-[2.5rem] overflow-hidden shadow-xl">
                <div className="p-8 border-b border-border flex items-center justify-between bg-muted/10">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-primary/10 flex items-center justify-center text-primary">
                            <Icon name="History" size={24} />
                        </div>
                        <div>
                            <h3 className="text-xl font-bold">Transaction History</h3>
                            <p className="text-xs text-muted-foreground uppercase tracking-widest font-bold">Ledger Records</p>
                        </div>
                    </div>
                </div>

                <div className="p-4">
                    {isLoading ? (
                        <div className="py-20 flex flex-col items-center justify-center opacity-50">
                            <Icon name="Loader2" size={32} className="animate-spin mb-4" />
                            <p className="text-sm font-medium">Scanning blockchain ledger...</p>
                        </div>
                    ) : transactions.length === 0 ? (
                        <div className="py-20 text-center">
                            <div className="w-20 h-20 bg-muted rounded-full flex items-center justify-center mx-auto mb-6">
                                <Icon name="Inbox" size={32} className="text-muted-foreground/50" />
                            </div>
                            <p className="text-muted-foreground font-medium">No transactions found yet.</p>
                            <p className="text-xs text-muted-foreground mt-1">Start learning to earn your first credits!</p>
                        </div>
                    ) : (
                        <div className="space-y-1">
                            {transactions.map((tx) => (
                                <div key={tx.id} className="group flex items-center justify-between p-4 rounded-2xl hover:bg-muted/50 transition-all border border-transparent hover:border-border/50">
                                    <div className="flex items-center gap-4">
                                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-transform group-hover:scale-110 duration-300 ${tx.amount > 0 ? 'bg-emerald-500/10 text-emerald-500' : 'bg-red-500/10 text-red-500'}`}>
                                            <Icon name={getTransactionIcon(tx.transaction_type)} size={20} />
                                        </div>
                                        <div>
                                            <p className="font-bold text-sm text-foreground">{tx.description}</p>
                                            <div className="flex items-center gap-2 mt-0.5">
                                                <span className="text-[10px] font-black uppercase text-muted-foreground tracking-wider bg-muted px-2 py-0.5 rounded-md">
                                                    {tx.transaction_type.replace(/_/g, ' ')}
                                                </span>
                                                <span className="text-[10px] text-muted-foreground flex items-center gap-1">
                                                    <Icon name="Clock" size={8} />
                                                    {new Date(tx.created_at).toLocaleDateString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className={`text-lg font-black tracking-tighter ${getTransactionColor(tx.amount)}`}>
                                            {tx.amount > 0 ? '+' : ''}{formatAmount(tx.amount)}
                                        </p>
                                        <p className="text-[9px] font-bold text-muted-foreground uppercase tracking-widest mt-0.5">LUC Credits</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
                
                {transactions.length > 0 && (
                    <div className="p-6 bg-muted/10 border-t border-border flex justify-center">
                        <Button variant="ghost" size="sm" className="text-muted-foreground hover:text-primary">
                            Load More Records
                        </Button>
                    </div>
                )}
            </div>

            <SendCreditsModal 
                isOpen={isSendModalOpen}
                onClose={() => setIsSendModalOpen(false)}
                senderId={userId}
                currentBalance={wallet.balance}
                onTransferSuccess={fetchWalletData}
            />

            {/* Withdraw Modal */}
            <Modal
                isOpen={isWithdrawModalOpen}
                onClose={() => setIsWithdrawModalOpen(false)}
                title="Withdraw LUC Credits"
                size="md"
            >
                <form onSubmit={handleWithdrawRequest} className="space-y-6 p-2">
                    <div className="p-4 bg-indigo-500/5 border border-indigo-500/20 rounded-2xl">
                        <p className="text-xs text-indigo-500 font-bold leading-relaxed">
                            <Icon name="Info" size={12} className="inline mr-1" />
                            1 LUC = ₦10. Minimum withdrawal: 100 LUC (₦1,000). Requests are reviewed and processed manually by admin.
                        </p>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">
                            Amount (LUC)
                        </label>
                        <input 
                            type="number" 
                            placeholder="e.g. 500"
                            min="100"
                            max={wallet.balance}
                            className="w-full h-14 bg-muted border border-border rounded-xl px-6 font-black italic focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                            value={withdrawForm.amount}
                            onChange={(e) => setWithdrawForm({...withdrawForm, amount: e.target.value})}
                            required
                        />
                        <p className="text-[10px] text-muted-foreground ml-1">
                            ≈ {formatNaira(lucToNaira(parseFloat(withdrawForm.amount) || 0))} | Available: {formatAmount(wallet.balance)} LUC
                        </p>
                    </div>

                    <div className="grid grid-cols-1 gap-4">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Bank Name</label>
                            <input 
                                type="text" 
                                placeholder="e.g. GTBank, Access Bank, etc."
                                className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                                value={withdrawForm.bank_name}
                                onChange={(e) => setWithdrawForm({...withdrawForm, bank_name: e.target.value})}
                                required
                            />
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Account Number</label>
                                <input 
                                    type="text" 
                                    placeholder="0123456789"
                                    className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                                    value={withdrawForm.account_number}
                                    onChange={(e) => setWithdrawForm({...withdrawForm, account_number: e.target.value})}
                                    required
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Account Holder Name</label>
                                <input 
                                    type="text" 
                                    placeholder="Your full name"
                                    className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                                    value={withdrawForm.account_name}
                                    onChange={(e) => setWithdrawForm({...withdrawForm, account_name: e.target.value})}
                                    required
                                />
                            </div>
                        </div>
                    </div>

                    <Button 
                        type="submit" 
                        fullWidth 
                        className="h-14 bg-indigo-600 hover:bg-indigo-700 text-white font-black italic rounded-xl"
                        isLoading={isSubmitting}
                    >
                        SUBMIT WITHDRAWAL REQUEST
                    </Button>
                </form>
            </Modal>
        </div>
    );
};

export default LUCWallet;