import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Modal from '../../../components/ui/Modal';
import Input from '../../../components/ui/Input';
import { cn } from '../../../utils/cn';
import { trackEvent } from '../../../utils/analytics';

const GoalCenter = () => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [goals, setGoals] = useState([
        {
            id: 1,
            title: 'Complete "The Triple Lock" Certification',
            category: 'study',
            progress: 65,
            deadline: '2026-06-15',
            priority: 'high'
        },
        {
            id: 2,
            title: 'Draft "Global Impact" Grant Proposal',
            category: 'research',
            progress: 30,
            deadline: '2026-05-30',
            priority: 'medium'
        },
        {
            id: 3,
            title: 'Ship Recruiter Portal Beta',
            category: 'project',
            progress: 85,
            deadline: '2026-05-20',
            priority: 'urgent'
        }
    ]);

    const [newGoal, setNewGoal] = useState({
        title: '',
        category: 'study',
        deadline: '',
        priority: 'medium'
    });

    const handleAddGoal = (e) => {
        e.preventDefault();
        const goal = {
            id: Date.now(),
            ...newGoal,
            progress: 0
        };

        // Track the goal creation in GA
        trackEvent('Missions', 'Create Goal', `${newGoal.category} - ${newGoal.priority}`);

        setGoals([goal, ...goals]);
        setIsModalOpen(false);
        setNewGoal({ title: '', category: 'study', deadline: '', priority: 'medium' });
    };

    const categories = {
        study: { icon: 'BookOpen', color: 'text-blue-500', bg: 'bg-blue-500/10', label: 'Studying' },
        research: { icon: 'Search', color: 'text-purple-500', bg: 'bg-purple-500/10', label: 'Research' },
        project: { icon: 'Cpu', color: 'text-emerald-500', bg: 'bg-emerald-500/10', label: 'Projects' }
    };

    const priorities = {
        urgent: 'bg-rose-500 text-white',
        high: 'bg-amber-500 text-white',
        medium: 'bg-slate-200 dark:bg-white/10 text-slate-600 dark:text-slate-400'
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter italic uppercase">
                        The Goal <span className="text-primary italic">Engine.</span>
                    </h2>
                    <p className="text-slate-500 dark:text-slate-400 font-medium">Define your target. Execute with precision.</p>
                </div>
                <Button 
                    onClick={() => setIsModalOpen(true)}
                    iconName="Plus"
                    className="rounded-2xl font-black italic"
                >
                    SET NEW GOAL
                </Button>
            </div>

            {/* Stats Overview */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {Object.keys(categories).map((key) => {
                    const catGoals = goals.filter(g => g.category === key);
                    const avgProgress = catGoals.length > 0 
                        ? Math.round(catGoals.reduce((acc, g) => acc + g.progress, 0) / catGoals.length) 
                        : 0;

                    return (
                        <div key={key} className="p-6 bg-card border border-border rounded-3xl shadow-sm relative overflow-hidden group">
                            <div className={cn("absolute top-0 right-0 w-24 h-24 blur-3xl opacity-10 -mr-8 -mt-8 transition-opacity group-hover:opacity-20", categories[key].bg)} />
                            <div className="flex items-center gap-3 mb-4">
                                <div className={cn("w-10 h-10 rounded-xl flex items-center justify-center", categories[key].bg, categories[key].color)}>
                                    <Icon name={categories[key].icon} size={20} />
                                </div>
                                <h3 className="text-sm font-black uppercase tracking-widest text-slate-500">{categories[key].label}</h3>
                            </div>
                            <div className="flex items-end justify-between">
                                <div>
                                    <p className="text-3xl font-black text-slate-900 dark:text-white">{catGoals.length}</p>
                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Active Goals</p>
                                </div>
                                <div className="text-right">
                                    <p className={cn("text-lg font-black italic", categories[key].color)}>{avgProgress}%</p>
                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Avg. Progress</p>
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Goals List */}
            <div className="space-y-4">
                {goals.map((goal) => (
                    <div key={goal.id} className="p-6 bg-card border border-border rounded-[2rem] shadow-sm hover:border-primary/30 transition-all group">
                        <div className="flex flex-col md:flex-row gap-6">
                            <div className="flex-1 space-y-4">
                                <div className="flex items-start justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={cn("w-8 h-8 rounded-lg flex items-center justify-center", categories[goal.category].bg, categories[goal.category].color)}>
                                            <Icon name={categories[goal.category].icon} size={16} />
                                        </div>
                                        <h4 className="text-lg font-bold text-slate-900 dark:text-white tracking-tight group-hover:text-primary transition-colors">{goal.title}</h4>
                                    </div>
                                    <span className={cn("px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest", priorities[goal.priority])}>
                                        {goal.priority}
                                    </span>
                                </div>

                                <div className="space-y-2">
                                    <div className="flex justify-between text-[10px] font-black uppercase tracking-widest text-slate-500">
                                        <span>Progress</span>
                                        <span>{goal.progress}%</span>
                                    </div>
                                    <div className="h-2 w-full bg-slate-100 dark:bg-white/5 rounded-full overflow-hidden">
                                        <div 
                                            className="h-full bg-primary transition-all duration-1000 ease-out"
                                            style={{ width: `${goal.progress}%` }}
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-6 md:pl-6 md:border-l border-border">
                                <div className="text-center min-w-[100px]">
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Deadline</p>
                                    <p className="text-sm font-bold text-slate-700 dark:text-slate-300 italic">{goal.deadline}</p>
                                </div>
                                <div className="flex gap-2">
                                    <button className="p-3 bg-slate-100 dark:bg-white/5 hover:bg-primary/10 hover:text-primary rounded-xl transition-all">
                                        <Icon name="Edit3" size={18} />
                                    </button>
                                    <button className="p-3 bg-slate-100 dark:bg-white/5 hover:bg-emerald-500/10 hover:text-emerald-500 rounded-xl transition-all">
                                        <Icon name="CheckCircle2" size={18} />
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Add Goal Modal */}
            <Modal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                title="Set New Mission"
                size="sm"
                footer={
                    <div className="flex w-full gap-3">
                        <Button variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                        <Button variant="default" className="flex-1 font-black italic" onClick={handleAddGoal}>START MISSION</Button>
                    </div>
                }
            >
                <div className="space-y-4">
                    <Input 
                        label="Goal Title" 
                        placeholder="e.g. Complete AI Ethics Research Paper"
                        value={newGoal.title}
                        onChange={(e) => setNewGoal({...newGoal, title: e.target.value})}
                    />
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Category</label>
                            <select 
                                className="w-full bg-slate-50 dark:bg-white/5 border border-border rounded-xl px-4 py-3 text-sm font-medium focus:outline-none focus:border-primary"
                                value={newGoal.category}
                                onChange={(e) => setNewGoal({...newGoal, category: e.target.value})}
                            >
                                <option value="study">Studying</option>
                                <option value="research">Researching</option>
                                <option value="project">Project / Building</option>
                            </select>
                        </div>
                        <Input 
                            label="Deadline" 
                            type="date"
                            value={newGoal.deadline}
                            onChange={(e) => setNewGoal({...newGoal, deadline: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Priority</label>
                        <div className="flex gap-2">
                            {['medium', 'high', 'urgent'].map((p) => (
                                <button
                                    key={p}
                                    onClick={() => setNewGoal({...newGoal, priority: p})}
                                    className={cn(
                                        "flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all",
                                        newGoal.priority === p 
                                            ? "bg-primary text-white border-primary" 
                                            : "bg-slate-50 dark:bg-white/5 border-border text-slate-400 hover:border-primary/50"
                                    )}
                                >
                                    {p}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </Modal>
        </div>
    );
};

export default GoalCenter;
