import React, { useState, useEffect, useMemo } from 'react';
import { useSelector } from 'react-redux';
import Icon from '../../../components/AppIcon';
import { supabaseService } from '../../../services/supabaseService';
import { cn } from '../../../utils/cn';

const ConsistencyHeatmap = () => {
    const { user } = useSelector((state) => state.auth);
    const [liveData, setLiveData] = useState({});
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchActivity = async () => {
            if (!user?.id) return;
            try {
                const data = await supabaseService.getUserActivityTimeline(user.id);
                setLiveData(data);
            } catch (err) {
                console.error("Failed to load activity heatmap:", err);
            } finally {
                setLoading(false);
            }
        };
        fetchActivity();
    }, [user?.id]);

    // Generate 365 days of data based on live counts
    const activityData = useMemo(() => {
        const data = [];
        const today = new Date();
        for (let i = 364; i >= 0; i--) {
            const date = new Date(today);
            date.setDate(date.getDate() - i);
            const dateStr = date.toISOString().split('T')[0];
            const count = liveData[dateStr] || 0;
            
            // Map count to level (0-4)
            let level = 0;
            if (count > 0) level = 1;
            if (count > 2) level = 2;
            if (count > 5) level = 3;
            if (count > 8) level = 4;
            
            data.push({ date, level, count });
        }
        return data;
    }, [liveData]);

    // Streak Calculations
    const stats = useMemo(() => {
        const dates = Object.keys(liveData).sort().reverse(); // Newest first
        if (dates.length === 0) return { current: 0, longest: 0, total: 0 };

        let currentStreak = 0;
        let longestStreak = 0;
        let tempStreak = 0;
        let totalActions = Object.values(liveData).reduce((a, b) => a + b, 0);

        // Calculate current streak (starting from today or yesterday)
        const todayStr = new Date().toISOString().split('T')[0];
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        const yesterdayStr = yesterday.toISOString().split('T')[0];

        let checkDate = new Date();
        while (true) {
            const str = checkDate.toISOString().split('T')[0];
            if (liveData[str]) {
                currentStreak++;
                checkDate.setDate(checkDate.getDate() - 1);
            } else {
                // If today is empty but yesterday had activity, the streak is still alive
                if (str === todayStr && liveData[yesterdayStr]) {
                    checkDate.setDate(checkDate.getDate() - 1);
                    continue;
                }
                break;
            }
        }

        // Calculate longest streak
        const sortedDates = Object.keys(liveData).sort();
        if (sortedDates.length > 0) {
            let lastDate = new Date(sortedDates[0]);
            tempStreak = 1;
            longestStreak = 1;

            for (let i = 1; i < sortedDates.length; i++) {
                const currentDate = new Date(sortedDates[i]);
                const diffTime = Math.abs(currentDate - lastDate);
                const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

                if (diffDays === 1) {
                    tempStreak++;
                } else {
                    tempStreak = 1;
                }
                longestStreak = Math.max(longestStreak, tempStreak);
                lastDate = currentDate;
            }
        }

        return { current: currentStreak, longest: longestStreak, total: totalActions };
    }, [liveData]);

    // Group into weeks (7 days per column)
    const weeks = useMemo(() => {
        const chunks = [];
        for (let i = 0; i < activityData.length; i += 7) {
            chunks.push(activityData.slice(i, i + 7));
        }
        return chunks;
    }, [activityData]);

    const getLevelColor = (level) => {
        switch(level) {
            case 1: return 'bg-emerald-500/20'; // light green
            case 2: return 'bg-emerald-500/50'; // medium green
            case 3: return 'bg-emerald-500/80'; // dark green
            case 4: return 'bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,0.5)]'; // intense green with glow
            default: return 'bg-white/5 border border-white/5'; // empty
        }
    };

    if (loading) {
        return (
            <div className="bg-slate-900 border border-white/10 rounded-3xl p-6 h-[280px] flex items-center justify-center">
                <div className="animate-pulse flex flex-col items-center gap-4">
                    <div className="w-12 h-12 bg-white/5 rounded-2xl" />
                    <div className="h-4 w-32 bg-white/5 rounded-full" />
                </div>
            </div>
        );
    }

    return (
        <div className="bg-slate-900 border border-white/10 rounded-3xl p-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/5 blur-[100px] rounded-full pointer-events-none" />
            
            <div className="relative z-10">
                <div className="flex items-center justify-between mb-6">
                    <div>
                        <div className="flex items-center gap-2 mb-1">
                            <Icon name="Activity" size={18} className="text-emerald-500" />
                            <h3 className="text-lg font-black text-white italic uppercase tracking-tighter">Application Streak</h3>
                        </div>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Global proof of work consistency</p>
                    </div>
                    <div className="text-right">
                        <div className="text-2xl font-black text-white italic">{stats.current} <span className="text-sm text-emerald-500 uppercase">Days</span></div>
                        <p className="text-[10px] uppercase tracking-widest text-slate-500 font-bold">Current Streak</p>
                    </div>
                </div>

                {/* Heatmap Grid */}
                <div className="overflow-x-auto pb-4 scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent">
                    <div className="flex gap-1.5 min-w-max">
                        {weeks.map((week, weekIdx) => (
                            <div key={weekIdx} className="flex flex-col gap-1.5">
                                {week.map((day, dayIdx) => (
                                    <div 
                                        key={dayIdx} 
                                        className={cn(
                                            "w-3.5 h-3.5 rounded-sm transition-all duration-300 hover:scale-150 cursor-pointer border border-transparent hover:z-20",
                                            getLevelColor(day.level)
                                        )}
                                        title={`${day.count} activities on ${day.date.toDateString()}`}
                                    />
                                ))}
                            </div>
                        ))}
                    </div>
                </div>

                <div className="flex items-center justify-between mt-4 border-t border-white/5 pt-4">
                    <div className="flex gap-8">
                        <div className="flex flex-col">
                            <span className="text-xl font-black text-white italic leading-none">{stats.total}</span>
                            <span className="text-[9px] uppercase tracking-widest text-slate-500 font-black mt-1">Total Actions</span>
                        </div>
                        <div className="w-px h-8 bg-white/10" />
                        <div className="flex flex-col">
                            <span className="text-xl font-black text-white italic leading-none">{stats.longest}</span>
                            <span className="text-[9px] uppercase tracking-widest text-slate-500 font-black mt-1">Longest Streak</span>
                        </div>
                    </div>

                    <div className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                        Less
                        <div className="flex gap-1">
                            <div className="w-3 h-3 rounded-sm bg-white/5 border border-white/5" />
                            <div className="w-3 h-3 rounded-sm bg-emerald-500/20" />
                            <div className="w-3 h-3 rounded-sm bg-emerald-500/50" />
                            <div className="w-3 h-3 rounded-sm bg-emerald-500/80" />
                            <div className="w-3 h-3 rounded-sm bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.3)]" />
                        </div>
                        More
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ConsistencyHeatmap;
