import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import { cn } from '../../../utils/cn';

const AnnouncementFeed = ({ enrolledCourseIds = [] }) => {
    const [announcements, setAnnouncements] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        fetchAnnouncements();
    }, [enrolledCourseIds.join(',')]);

    const fetchAnnouncements = async () => {
        setIsLoading(true);
        try {
            // Only fetch if student has enrollments
            if (enrolledCourseIds.length > 0) {
                const data = await supabaseService.getStudentAnnouncements(enrolledCourseIds);
                setAnnouncements(data);
            }
        } catch (error) {
            console.error('Failed to fetch announcement feed:', error);
        } finally {
            setIsLoading(false);
        }
    };

    if (isLoading) {
        return (
            <div className="flex justify-center py-10">
                <div className="w-8 h-8 border-2 border-secondary border-t-transparent rounded-full animate-spin" />
            </div>
        );
    }

    if (announcements.length === 0) return null;

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-1000">
            <div className="flex items-center gap-3 px-2">
                <div className="w-8 h-8 rounded-full bg-secondary/10 flex items-center justify-center text-secondary">
                    <Icon name="Bell" size={16} />
                </div>
                <h4 className="text-sm font-black text-primary uppercase tracking-widest italic">Announcements</h4>
            </div>

            <div className="space-y-4">
                {announcements.map((ann) => (
                    <div 
                        key={ann.id} 
                        className={cn(
                            "relative p-6 rounded-[2rem] border transition-all hover:scale-[1.02]",
                            ann.is_critical 
                                ? "bg-destructive/5 border-destructive/20 shadow-lg shadow-destructive/5" 
                                : "bg-card border-border shadow-sm hover:shadow-md"
                        )}
                    >
                        {ann.is_critical && (
                            <div className="absolute -top-2 -right-2 bg-destructive text-white p-1.5 rounded-full animate-pulse shadow-lg">
                                <Icon name="AlertTriangle" size={14} />
                            </div>
                        )}

                        <div className="flex items-start gap-4">
                            <div className="w-10 h-10 rounded-full bg-slate-900 border border-white/5 overflow-hidden shrink-0">
                                <img 
                                    src={ann.instructor?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(ann.instructor?.full_name)}`} 
                                    className="w-full h-full object-cover" 
                                />
                            </div>
                            <div className="flex-1 space-y-2">
                                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                                    <h5 className="font-bold text-sm text-primary italic leading-none">{ann.title}</h5>
                                    <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">
                                        {new Date(ann.created_at).toLocaleDateString()}
                                    </span>
                                </div>
                                <p className="text-xs text-muted-foreground leading-relaxed">
                                    {ann.content}
                                </p>
                                <div className="flex items-center gap-2 pt-2">
                                    <span className="text-[9px] font-bold text-primary/60 italic">
                                        — {ann.instructor?.full_name}
                                    </span>
                                    <span className="text-[8px] font-black text-secondary uppercase tracking-[0.2em] px-2 py-0.5 rounded-md bg-secondary/10">
                                        {ann.type}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default AnnouncementFeed;
